// Shared helpers for the pages built from the Telegram channel export (/goodnight,
// /communityshowcase, /movies). The JSON next to this file is generated by
// scripts/channel/build.py.

export const CHANNEL = 'Dagmawi_Babi';

export const postUrl = (id: number) => `https://t.me/${CHANNEL}/${id}`;

const longDate = new Intl.DateTimeFormat('en', { day: 'numeric', month: 'short', year: 'numeric' });
const shortDate = new Intl.DateTimeFormat('en', { month: 'short', year: 'numeric' });

/** Export dates are local wall-clock times without a zone; read them as such. */
export const parseDate = (s: string) => new Date(s.length === 10 ? s + 'T00:00:00' : s);
export const fmtDate = (s: string) => longDate.format(parseDate(s));
export const fmtMonth = (s: string) => shortDate.format(parseDate(s));

export function relative(s: string, now = new Date()) {
	const days = Math.floor((now.getTime() - parseDate(s).getTime()) / 86400000);
	if (days < 1) return 'today';
	if (days < 2) return 'yesterday';
	if (days < 30) return `${days} days ago`;
	if (days < 365) return `${Math.floor(days / 30)} mo ago`;
	const y = Math.floor(days / 365);
	return `${y} yr${y > 1 ? 's' : ''} ago`;
}

export const compact = new Intl.NumberFormat('en', { notation: 'compact', maximumFractionDigits: 1 });

/** Small deterministic hash, for picking colours and layouts per post. */
export function hash(n: number | string) {
	let h = 2166136261;
	const s = String(n);
	for (let i = 0; i < s.length; i++) {
		h ^= s.charCodeAt(i);
		h = Math.imul(h, 16777619);
	}
	return h >>> 0;
}

/** A post body run: [kind, text, href?] — kind is t(ext), a(link), b(old), i(talic) or c(ode). */
export type Segment = [string, string, string?];
